//! Current membership lives at immutable identity homes. Only admitted clean,
//! dirty and pinned records are resident; posting actors do not mirror them.
use anyhow::{ensure,Result};
use chroma_blockstore::{provider::BlockfileProvider,arrow::provider::BlockfileReaderOptions,BlockfileWriterOptions};
use parking_lot::{Mutex,MutexGuard};
use std::{collections::{BTreeMap,BTreeSet},sync::atomic::{AtomicU64,Ordering}};
use uuid::Uuid;
use super::{partition_authority::VectorId64,owner_vector_store::VectorHandle,persistence::block_on_for_sync_writer};
const MAGIC:u32=0x564d4431;
#[derive(Clone,Debug,PartialEq,Eq)]pub(super) struct Record{pub active:bool,pub owner:usize,pub epoch:u64,pub version:u8,pub handle:VectorHandle,pub revision:u64}
#[derive(Clone,Copy,Debug)]pub struct Limits{pub clean_records:usize,pub dirty_records:usize,pub pin_records:usize,pub record_bytes:usize}
impl Default for Limits{fn default()->Self{Self{clean_records:8,dirty_records:128,pin_records:256,record_bytes:256}}}
struct Entry{value:Option<Record>,revision:u64,loaded:bool,pins:usize,writers:usize,dirty:bool,tick:u64}
struct State{pending:usize,root:Option<Uuid>,entries:BTreeMap<u32,Entry>,tick:u64,records:usize,loads:Vec<usize>,dirty_reserved:usize,new_reserved:usize,pins:usize,peak_pins:usize,peak_entries:usize,evictions:u64}
struct Home{state:Mutex<State>,flush:Mutex<()>}
pub struct Store{provider:BlockfileProvider,homes:BTreeMap<u32,Home>,pub limits:Limits,dim:usize,owners:usize,capacity:usize,revision:AtomicU64,reads:AtomicU64,decoded:AtomicU64,commits:AtomicU64}
#[derive(Clone)]struct Change{key:u32,value:Option<Record>,revision:u64}
struct Flush{home:u32,parent:Option<Uuid>,changes:Vec<Change>,summary:Vec<u32>}
/// Pins are IDs, not copied versions. Every read consults the current cached
/// entry; mutations update it even when another request retains a pin.
pub(super) struct Prepared<'a>{store:&'a Store,ids:Vec<VectorId64>,credits:BTreeMap<VectorId64,(bool,bool)>}
impl Store{
 pub fn new(provider:BlockfileProvider,homes:&[u32],dim:usize,owners:usize,capacity:usize,limits:Limits)->Result<Self>{
  ensure!(!homes.is_empty()&&homes.len()<=64&&owners>0&&owners<=8&&dim>0&&dim<=768&&capacity>0,"metadata home admission");ensure!(limits.clean_records>0&&limits.dirty_records>0&&limits.pin_records>=64&&limits.record_bytes>=std::mem::size_of::<Record>()+64,"metadata working admission");ensure!(limits.clean_records.checked_add(limits.dirty_records).and_then(|v|v.checked_add(limits.pin_records)).and_then(|v|v.checked_mul(limits.record_bytes)).is_some(),"metadata capacity overflow");let mut owned=BTreeMap::new();for home in homes{ensure!(!owned.contains_key(home),"duplicate metadata home");owned.insert(*home,Home{state:Mutex::new(State{pending:0,root:None,entries:BTreeMap::new(),tick:0,records:0,loads:vec![0;owners],dirty_reserved:0,new_reserved:0,pins:0,peak_pins:0,peak_entries:0,evictions:0}),flush:Mutex::new(())});}Ok(Self{provider,homes:owned,limits,dim,owners,capacity,revision:AtomicU64::new(1),reads:AtomicU64::new(0),decoded:AtomicU64::new(0),commits:AtomicU64::new(0)})
 }
 pub fn home_ids(&self)->Vec<u32>{self.homes.keys().copied().collect()}
 pub fn admits(&self,id:VectorId64)->bool{self.homes.contains_key(&id.home())}
 fn state(&self,home:u32)->MutexGuard<'_,State>{self.homes[&home].state.lock()}
 fn evict(&self,s:&mut State){while s.entries.values().filter(|e|!e.dirty&&e.pins==0).count()>self.limits.clean_records{let key=*s.entries.iter().filter(|(_,e)|!e.dirty&&e.pins==0).min_by_key(|(_,e)|e.tick).unwrap().0;s.entries.remove(&key);s.evictions+=1;}s.peak_entries=s.peak_entries.max(s.entries.len());}
 fn pin_one(&self,id:VectorId64)->Result<()>{
  {let mut s=self.state(id.home());ensure!(s.pins<self.limits.pin_records,"metadata pin admission");s.pins+=1;s.peak_pins=s.peak_pins.max(s.pins);s.tick+=1;let tick=s.tick;let e=s.entries.entry(id.local()).or_insert(Entry{value:None,revision:0,loaded:false,pins:0,writers:0,dirty:false,tick});e.pins+=1;e.tick=tick;self.evict(&mut s);}
  let result=(||{for _ in 0..64{let root={let s=self.state(id.home());if s.entries[&id.local()].loaded{return Ok(());}s.root};let value=if let Some(root)=root{self.reads.fetch_add(1,Ordering::Relaxed);let value=read_saved(&self.provider,root,id,self.dim,self.owners)?;if value.is_some(){self.decoded.fetch_add(1,Ordering::Relaxed);}value}else{None};let mut s=self.state(id.home());if s.entries[&id.local()].loaded{return Ok(());}if s.root!=root{continue;}let e=s.entries.get_mut(&id.local()).unwrap();e.revision=value.as_ref().map_or(0,|v|v.revision);e.value=value;e.loaded=true;return Ok(());}anyhow::bail!("metadata root changed repeatedly")})();
  if result.is_err(){self.unpin(id);}result
 }
 fn unpin(&self,id:VectorId64){let mut s=self.state(id.home());s.pins-=1;s.entries.get_mut(&id.local()).unwrap().pins-=1;self.evict(&mut s);}
 pub(super) fn prepare(&self,ids:&[VectorId64],write:bool)->Result<Prepared<'_>>{
  ensure!(ids.len()<=64&&ids.iter().all(|id|self.admits(*id)),"metadata request admission");let mut keys=ids.to_vec();keys.sort_unstable();keys.dedup();let mut prepared=Prepared{store:self,ids:vec![],credits:BTreeMap::new()};for id in keys{self.pin_one(id)?;prepared.ids.push(id);}
  if write{let homes:BTreeSet<_>=prepared.ids.iter().map(|id|id.home()).collect();for home in homes{let keys:Vec<_>=prepared.ids.iter().filter(|id|id.home()==home).copied().collect();for attempt in 0..2{let mut s=self.state(home);let dirty=keys.iter().filter(|id|!s.entries[&id.local()].dirty).count();if s.entries.values().filter(|e|e.dirty).count()+s.dirty_reserved+dirty>self.limits.dirty_records{drop(s);ensure!(attempt==0,"metadata dirty admission after flush");self.flush_home(home)?;continue;}let new=keys.iter().filter(|id|s.entries[&id.local()].value.is_none()).count();ensure!(s.records.checked_add(s.new_reserved).and_then(|n|n.checked_add(new)).is_some_and(|n|n<=self.capacity),"metadata record capacity");s.dirty_reserved+=dirty;s.new_reserved+=new;for id in &keys{let e=&s.entries[&id.local()];let credit=(!e.dirty,e.value.is_none());s.entries.get_mut(&id.local()).unwrap().writers+=1;prepared.credits.insert(*id,credit);}break;}}}
  Ok(prepared)
 }
 pub fn remaining(&self,home:u32)->usize{let s=self.state(home);self.capacity-s.records-s.new_reserved}
 pub fn owner_loads(&self)->Vec<usize>{let mut loads=vec![0;self.owners];for home in self.homes.keys(){for(a,b)in loads.iter_mut().zip(&self.state(*home).loads){*a+=*b;}}loads}
 fn snapshot(&self,home:u32)->Flush{let s=self.state(home);let changes=s.entries.iter().filter(|(_,e)|e.dirty).map(|(key,e)|Change{key:*key,value:e.value.clone(),revision:e.revision}).collect();let mut summary=vec![MAGIC,1,self.dim as u32,self.owners as u32,s.records as u32,(s.records as u64>>32)as u32];for count in &s.loads{summary.extend([*count as u32,(*count as u64>>32)as u32]);}Flush{home,parent:s.root,changes,summary}}
 fn write_flush(&self,snapshot:&Flush)->Result<Uuid>{block_on_for_sync_writer(async{let mut options=BlockfileWriterOptions::new(String::new()).ordered_mutations().max_block_size_bytes(16*1024);if let Some(root)=snapshot.parent{options=options.fork(root);}let writer=self.provider.write::<u32,Vec<u32>>(options).await.map_err(|e|anyhow::anyhow!("{e}"))?;for change in &snapshot.changes{if let Some(value)=&change.value{writer.set("record",change.key,encode(value)).await.map_err(|e|anyhow::anyhow!("{e}"))?;}else{writer.delete::<_,Vec<u32>>("record",change.key).await.map_err(|e|anyhow::anyhow!("{e}"))?;}}writer.set("summary",0,snapshot.summary.clone()).await.map_err(|e|anyhow::anyhow!("{e}"))?;let flusher=writer.commit::<u32,Vec<u32>>().await.map_err(|e|anyhow::anyhow!("{e}"))?;let root=flusher.id();flusher.flush::<u32,Vec<u32>>().await.map_err(|e|anyhow::anyhow!("{e}"))?;self.commits.fetch_add(1,Ordering::Relaxed);Ok(root)})}
 fn ack(&self,snapshot:&Flush,root:Uuid){let mut s=self.state(snapshot.home);s.root=Some(root);for change in &snapshot.changes{if let Some(e)=s.entries.get_mut(&change.key){if e.revision==change.revision&&e.writers==0{e.dirty=false;}}}self.evict(&mut s);}
 fn flush_home(&self,home:u32)->Result<Uuid>{let _gate=self.homes[&home].flush.lock();let snapshot=self.snapshot(home);if snapshot.changes.is_empty(){if let Some(root)=snapshot.parent{return Ok(root);}}let root=self.write_flush(&snapshot)?;self.ack(&snapshot,root);Ok(root)}
 pub fn flush(&self)->Result<BTreeMap<u32,Uuid>>{let publication=self.prepare_publication()?;let roots=publication.roots.clone();publication.acknowledge();Ok(roots)}
 pub(super) fn prepare_publication(&self)->Result<Publication<'_>>{let gates:Vec<_>=self.homes.values().map(|h|h.flush.lock()).collect();ensure!(self.homes.values().all(|h|h.state.lock().pending==0),"publication with pending metadata");let snapshots:Vec<_>=self.homes.keys().map(|home|self.snapshot(*home)).collect();let mut roots=BTreeMap::new();for snapshot in &snapshots{let root=if snapshot.changes.is_empty()&&snapshot.parent.is_some(){snapshot.parent.unwrap()}else{self.write_flush(snapshot)?};roots.insert(snapshot.home,root);}Ok(Publication{store:self,snapshots,roots,_gates:gates})}
 pub fn report(&self)->serde_json::Value{let homes:Vec<_>=self.homes.iter().map(|(id,home)|{let s=home.state.lock();serde_json::json!({"home":id,"entries":s.entries.len(),"dirty":s.entries.values().filter(|e|e.dirty).count(),"pins":s.pins,"peak_pins":s.peak_pins,"peak_entries":s.peak_entries,"evictions":s.evictions,"logical_records":s.records,"pending_records":s.pending,"loads":s.loads,"dirty_reserved":s.dirty_reserved,"new_reserved":s.new_reserved})}).collect();serde_json::json!({"policy":"paged-home-vector-metadata-v1","homes":homes,"point_reads":self.reads.load(Ordering::Relaxed),"decoded_records":self.decoded.load(Ordering::Relaxed),"commits":self.commits.load(Ordering::Relaxed),"clean_record_cap":self.limits.clean_records,"dirty_record_cap":self.limits.dirty_records,"pin_record_cap":self.limits.pin_records,"accounted_record_bytes":self.limits.record_bytes,"scope":"Bounded clean/dirty/pinned entries per immutable home. Record bytes are an admission model; encoded/provider/index/container/allocator buffers and RSS are separate."})}
}
pub(super) struct Publication<'a>{store:&'a Store,snapshots:Vec<Flush>,pub roots:BTreeMap<u32,Uuid>,_gates:Vec<MutexGuard<'a,()>>}
impl Publication<'_>{pub fn acknowledge(self){for snapshot in &self.snapshots{self.store.ack(snapshot,self.roots[&snapshot.home]);}}}
impl Prepared<'_>{
 pub(super) fn get(&self,id:VectorId64)->Result<Option<Record>>{ensure!(self.ids.binary_search(&id).is_ok(),"metadata ID is not pinned");let s=self.store.state(id.home());Ok(s.entries[&id.local()].value.clone())}
 pub(super) fn set(&mut self,id:VectorId64,mut value:Option<Record>)->Result<()>{ensure!(self.ids.binary_search(&id).is_ok(),"metadata ID is not pinned");let credit=self.credits.get_mut(&id).ok_or_else(||anyhow::anyhow!("metadata read-only pin"))?;let mut s=self.store.state(id.home());let previous=s.entries[&id.local()].value.clone();if !s.entries[&id.local()].dirty{ensure!(credit.0,"metadata dirty credit required");}if previous.is_none()&&value.is_some(){ensure!(credit.1,"metadata new credit required");}if let Some(v)=&value{validate(id,v,self.store.dim,self.store.owners)?;}if credit.0{s.dirty_reserved-=1;credit.0=false;}if credit.1{s.new_reserved-=1;credit.1=false;}if previous.is_none()&&value.is_some(){s.records+=1;}if previous.is_some()&&value.is_none(){s.records-=1;}if let Some(old)=&previous{if !old.active{s.pending-=1;}if old.active&&old.version&0x80==0{s.loads[old.owner]-=1;}}let revision=self.store.revision.fetch_add(1,Ordering::Relaxed);if let Some(new)=&mut value{new.revision=revision;if !new.active{s.pending+=1;}if new.active&&new.version&0x80==0{s.loads[new.owner]+=1;}}let e=s.entries.get_mut(&id.local()).unwrap();e.value=value;e.revision=revision;e.dirty=true;Ok(())}
}
impl Drop for Prepared<'_>{fn drop(&mut self){for(id,(dirty,new))in &self.credits{let mut s=self.store.state(id.home());s.entries.get_mut(&id.local()).unwrap().writers-=1;if *dirty{s.dirty_reserved-=1;}if *new{s.new_reserved-=1;}}for id in &self.ids{self.store.unpin(*id);}}}
fn validate(id:VectorId64,value:&Record,dim:usize,owners:usize)->Result<()>{ensure!(value.owner<owners&&value.handle.home==id.home()&&value.handle.key==id.local()&&value.handle.dim==dim,"metadata record identity/dimension/owner");Ok(())}
fn encode(v:&Record)->Vec<u32>{let mut w=vec![MAGIC,1,u32::from(v.active),v.owner as u32,(v.owner as u64>>32)as u32,v.epoch as u32,(v.epoch>>32)as u32,v.revision as u32,(v.revision>>32)as u32,u32::from(v.version)];for bytes in v.handle.root.as_bytes().chunks_exact(4){w.push(u32::from_le_bytes(bytes.try_into().unwrap()));}w.extend([v.handle.key,v.handle.home,v.handle.dim as u32,(v.handle.dim as u64>>32)as u32]);for b in v.handle.sha.chunks_exact(4){w.push(u32::from_le_bytes(b.try_into().unwrap()));}w}
fn decode(id:VectorId64,w:&[u32],dim:usize,owners:usize)->Result<Record>{ensure!(w.len()==26&&w[0]==MAGIC&&w[1]==1&&w[2]<=1&&w[9]<=255,"metadata codec header/extent");let wide=|i:usize|u64::from(w[i])|(u64::from(w[i+1])<<32);let mut root=[0;16];for(slot,word)in root.chunks_exact_mut(4).zip(&w[10..14]){slot.copy_from_slice(&word.to_le_bytes());}let mut sha=[0;32];for(slot,word)in sha.chunks_exact_mut(4).zip(&w[18..26]){slot.copy_from_slice(&word.to_le_bytes());}let value=Record{active:w[2]!=0,owner:usize::try_from(wide(3))?,epoch:wide(5),revision:wide(7),version:w[9]as u8,handle:VectorHandle{root:Uuid::from_bytes(root),key:w[14],home:w[15],dim:usize::try_from(wide(16))?,sha}};validate(id,&value,dim,owners)?;Ok(value)}
pub(super) fn read_saved(provider:&BlockfileProvider,root:Uuid,id:VectorId64,dim:usize,owners:usize)->Result<Option<Record>>{block_on_for_sync_writer(async{let reader=provider.read::<u32,&[u32]>(BlockfileReaderOptions::new(root,String::new())).await.map_err(|e|anyhow::anyhow!("{e}"))?;let result=reader.get("record",id.local()).await.map_err(|e|anyhow::anyhow!("{e}"))?.map(|words|decode(id,words,dim,owners)).transpose();reader.clear_loaded_blocks();result})}

/// Immutable roots never consult live home state. Returned rows are bounded by
/// the request cap, separately from this small decoded record cache.
pub(super) struct Saved{provider:BlockfileProvider,roots:BTreeMap<u32,Uuid>,dim:usize,owners:usize,cap:usize,cache:BTreeMap<VectorId64,Record>,order:std::collections::VecDeque<VectorId64>,reads:u64,opens:u64,peak_rows:usize}
impl Saved{
 pub fn new(provider:BlockfileProvider,roots:BTreeMap<u32,Uuid>,dim:usize,owners:usize,cap:usize)->Result<Self>{ensure!(!roots.is_empty()&&roots.len()<=64&&dim>0&&dim<=768&&owners>0&&owners<=8&&cap>0&&cap<=64,"saved metadata admission");Ok(Self{provider,roots,dim,owners,cap,cache:BTreeMap::new(),order:std::collections::VecDeque::new(),reads:0,opens:0,peak_rows:0})}
 pub fn records(&mut self,ids:&[VectorId64])->Result<Vec<Option<Record>>>{ensure!(ids.len()<=64&&ids.iter().all(|id|self.roots.contains_key(&id.home())),"saved metadata batch/home");let mut result=vec![None;ids.len()];let mut groups=BTreeMap::<u32,Vec<(usize,VectorId64)>>::new();for(slot,id)in ids.iter().enumerate(){if let Some(value)=self.cache.get(id){result[slot]=Some(value.clone());}else{groups.entry(id.home()).or_default().push((slot,*id));}}
  for(home,keys)in groups{self.opens+=1;self.reads+=keys.len()as u64;let root=self.roots[&home];let loaded=block_on_for_sync_writer(async{let reader=self.provider.read::<u32,&[u32]>(BlockfileReaderOptions::new(root,String::new())).await.map_err(|e|anyhow::anyhow!("{e}"))?;let mut values=vec![];for(_,id)in &keys{let value=reader.get("record",id.local()).await.map_err(|e|anyhow::anyhow!("{e}"))?.map(|words|decode(*id,words,self.dim,self.owners)).transpose()?;ensure!(value.as_ref().is_none_or(|v|v.active),"saved metadata contains pending record");values.push(value);}reader.clear_loaded_blocks();Ok::<_,anyhow::Error>(values)})?;for((slot,id),value)in keys.into_iter().zip(loaded){result[slot]=value.clone();if let Some(value)=value{if !self.cache.contains_key(&id){while self.cache.len()>=self.cap{self.cache.remove(&self.order.pop_front().unwrap());}self.order.push_back(id);}self.cache.insert(id,value);}}
  }self.peak_rows=self.peak_rows.max(ids.len());Ok(result)
 }
 pub fn report(&self)->serde_json::Value{serde_json::json!({"cached_records":self.cache.len(),"cache_cap":self.cap,"point_read_attempts":self.reads,"home_reader_opens":self.opens,"peak_returned_rows":self.peak_rows,"scope":"Pinned saved roots, <=64 returned metadata rows/request and bounded decoded cache. Encoded/provider/root-index buffers are separate; counters are not physical IO/network."})}
}

#[cfg(test)]mod tests{
 use super::*;use chroma_blockstore::arrow::provider::ArrowBlockfileProvider;use chroma_cache::new_cache_for_test;use chroma_storage::{Storage,local::LocalStorage};
 fn provider(path:&std::path::Path)->BlockfileProvider{BlockfileProvider::ArrowBlockfileProvider(ArrowBlockfileProvider::new(Storage::Local(LocalStorage::new(path.to_str().unwrap())),16*1024,new_cache_for_test(),new_cache_for_test(),2))}
 fn row(id:VectorId64)->Record{Record{active:true,owner:0,epoch:0,version:1,revision:0,handle:VectorHandle{root:Uuid::new_v4(),key:id.local(),home:id.home(),dim:32,sha:[7;32]}}}
 #[tokio::test(flavor="multi_thread",worker_threads=2)]async fn paged_metadata_publication_drop_and_newer_tombstone(){let dir=tempfile::tempdir().unwrap();let store=Store::new(provider(dir.path()),&[0,1],32,2,256,Limits{clean_records:2,dirty_records:8,pin_records:64,record_bytes:256}).unwrap();let ids=[VectorId64::new(0,1),VectorId64::new(1,1)];for id in ids{let mut pin=store.prepare(&[id],true).unwrap();pin.set(id,Some(row(id))).unwrap();}let old=store.flush().unwrap();for id in ids{let mut pin=store.prepare(&[id],true).unwrap();let mut value=pin.get(id).unwrap().unwrap();value.version=2;pin.set(id,Some(value)).unwrap();}{let unaccepted=store.prepare_publication().unwrap();assert_ne!(unaccepted.roots,old);}for home in [0,1]{assert_eq!(store.state(home).root,Some(old[&home]));assert_eq!(store.report()["homes"][home as usize]["dirty"],1);}let id=ids[0];{let mut pin=store.prepare(&[id],true).unwrap();pin.set(id,None).unwrap();}let snapshot=store.snapshot(0);{let mut pin=store.prepare(&[id],true).unwrap();pin.set(id,None).unwrap();}let root=store.write_flush(&snapshot).unwrap();store.ack(&snapshot,root);assert_eq!(store.report()["homes"][0]["dirty"],1,"newer tombstone must survive older acknowledgement");let roots=store.flush().unwrap();assert!(read_saved(&store.provider,roots[&0],id,32,2).unwrap().is_none());assert_eq!(read_saved(&store.provider,old[&0],id,32,2).unwrap().unwrap().version,1);}
 #[tokio::test(flavor="multi_thread",worker_threads=2)]async fn paged_metadata_write_credit_survives_flush(){let dir=tempfile::tempdir().unwrap();let store=Store::new(provider(dir.path()),&[0],32,2,256,Limits{clean_records:2,dirty_records:4,pin_records:64,record_bytes:256}).unwrap();let id=VectorId64::new(0,1);{let mut initial=store.prepare(&[id],true).unwrap();initial.set(id,Some(row(id))).unwrap();}let mut held=store.prepare(&[id],true).unwrap();store.flush_home(0).unwrap();assert_eq!(store.report()["homes"][0]["dirty"],1);let mut value=held.get(id).unwrap().unwrap();value.version=2;held.set(id,Some(value)).unwrap();store.flush_home(0).unwrap();let mut value=held.get(id).unwrap().unwrap();value.version=3;held.set(id,Some(value)).unwrap();drop(held);let read_only=store.prepare(&[id],false).unwrap();let roots=store.flush().unwrap();assert_eq!(read_saved(&store.provider,roots[&0],id,32,2).unwrap().unwrap().version,3);assert_eq!(store.report()["homes"][0]["dirty"],0);drop(read_only);}
 #[tokio::test(flavor="multi_thread",worker_threads=2)]async fn paged_metadata_core_eviction_live_pins_transfer_and_old_roots(){let dir=tempfile::tempdir().unwrap();let provider=provider(dir.path());let store=Store::new(provider.clone(),&[0,1],32,2,256,Limits{clean_records:2,dirty_records:64,pin_records:128,record_bytes:256}).unwrap();let ids:Vec<_>=(0..128u32).map(|id|VectorId64::new(id%2,id/2)).collect();for chunk in ids.chunks(64){let mut pin=store.prepare(chunk,true).unwrap();for id in chunk{pin.set(*id,Some(row(*id))).unwrap();}}let old=store.flush().unwrap();let pinned=store.prepare(&ids[..2],false).unwrap();let before=pinned.get(ids[0]).unwrap().unwrap();{let mut update=store.prepare(&ids[..1],true).unwrap();let mut next=update.get(ids[0]).unwrap().unwrap();next.owner=1;next.epoch+=1;next.version+=1;update.set(ids[0],Some(next)).unwrap();}assert_eq!(pinned.get(ids[0]).unwrap().unwrap().version,2,"pin reads current entry, not frozen version");drop(pinned);let current=store.flush().unwrap();assert_eq!(read_saved(&provider,old[&ids[0].home()],ids[0],32,2).unwrap().unwrap(),before);assert_eq!(read_saved(&provider,current[&ids[0].home()],ids[0],32,2).unwrap().unwrap().owner,1);for id in &ids{let pin=store.prepare(&[*id],false).unwrap();assert!(pin.get(*id).unwrap().unwrap().active);}assert_eq!(store.owner_loads(),vec![127,1]);let report=store.report();assert!(report["homes"].as_array().unwrap().iter().all(|h|h["evictions"].as_u64().unwrap()>0&&h["entries"].as_u64().unwrap()<=2&&h["pins"]==0));println!("PAGED_METADATA_CORE {}",report);}
 #[test]fn paged_metadata_codec_and_admission(){let id=VectorId64::new(1,7);let value=row(id);assert_eq!(decode(id,&encode(&value),32,2).unwrap(),value);for field in [0,1,2,9,14,15,16]{let mut bad=encode(&value);bad[field]=u32::MAX;assert!(decode(id,&bad,32,2).is_err());}assert!(decode(id,&encode(&value)[..25],32,2).is_err());}
}
